CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE personnel_levels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, label text NOT NULL, rank int UNIQUE NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE divisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, lead_user_id uuid, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), division_id uuid REFERENCES divisions, name text UNIQUE NOT NULL, slug text UNIQUE NOT NULL, lead_user_id uuid, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), myfwa_id text UNIQUE, email text UNIQUE, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 120), legal_name text,
 status text NOT NULL DEFAULT 'pending_identity' CHECK(status IN ('pending_identity','active','inactive','former')), primary_department_id uuid REFERENCES departments, personnel_level_id uuid REFERENCES personnel_levels,
 volunteer_eligible boolean NOT NULL DEFAULT false, dev_identity boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz
);
ALTER TABLE divisions ADD FOREIGN KEY(lead_user_id) REFERENCES users;
ALTER TABLE departments ADD FOREIGN KEY(lead_user_id) REFERENCES users;
CREATE TABLE user_departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, department_id uuid NOT NULL REFERENCES departments, joined_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, is_primary boolean NOT NULL DEFAULT false, membership_status text NOT NULL DEFAULT 'active');
CREATE UNIQUE INDEX one_primary_membership ON user_departments(user_id) WHERE is_primary AND ended_at IS NULL;
CREATE UNIQUE INDEX one_active_membership ON user_departments(user_id,department_id) WHERE ended_at IS NULL;
CREATE TABLE manager_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manager_user_id uuid NOT NULL REFERENCES users, direct_user_id uuid NOT NULL REFERENCES users, department_id uuid REFERENCES departments, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, CHECK(manager_user_id<>direct_user_id));
CREATE TABLE skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL);
CREATE TABLE user_skills (user_id uuid REFERENCES users, skill_id uuid REFERENCES skills, proficiency text, notes text, PRIMARY KEY(user_id,skill_id));
CREATE TABLE user_service_years (user_id uuid REFERENCES users, year int CHECK(year BETWEEN 1990 AND 2200), verification_status text NOT NULL CHECK(verification_status IN ('self_reported','verified')), verified_by_user_id uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,year));
CREATE TABLE permission_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, permission text NOT NULL, scope_type text NOT NULL CHECK(scope_type IN ('global','department','division')), scope_id uuid, granted_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), CHECK((scope_type='global')=(scope_id IS NULL)));
CREATE INDEX grants_user ON permission_grants(user_id);
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profile_field_definitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text UNIQUE NOT NULL, label text NOT NULL, type text NOT NULL CHECK(type IN ('text','number','date','boolean','single_select','multi_select','url')), validation_json jsonb NOT NULL DEFAULT '{}', choices_json jsonb NOT NULL DEFAULT '[]', visibility text NOT NULL DEFAULT 'self', editable_by text NOT NULL DEFAULT 'hr', required_for jsonb NOT NULL DEFAULT '[]', display_order int NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE profile_field_values (user_id uuid REFERENCES users, definition_id uuid REFERENCES profile_field_definitions, value_json jsonb NOT NULL, updated_by_user_id uuid REFERENCES users, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,definition_id));
CREATE TABLE terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, audience text NOT NULL CHECK(audience IN ('all','volunteers','personnel')), minimum_personnel_rank int, requires_volunteer boolean, active boolean NOT NULL DEFAULT true, effective_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz, created_by uuid REFERENCES users);
CREATE TABLE term_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), term_id uuid NOT NULL REFERENCES terms, version_number int NOT NULL, body_markdown text NOT NULL, body_sha256 text NOT NULL, published_at timestamptz, published_by uuid REFERENCES users, superseded_at timestamptz, UNIQUE(term_id,version_number));
CREATE UNIQUE INDEX one_current_version ON term_versions(term_id) WHERE published_at IS NOT NULL AND superseded_at IS NULL;
CREATE TABLE term_signatures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), term_version_id uuid NOT NULL REFERENCES term_versions, user_id uuid NOT NULL REFERENCES users, typed_name text NOT NULL, affirmation_text text NOT NULL, consented_at timestamptz NOT NULL DEFAULT now(), server_received_at timestamptz NOT NULL DEFAULT now(), document_sha256 text NOT NULL, method text NOT NULL DEFAULT 'authenticated_clickwrap_typed_name', UNIQUE(term_version_id,user_id));
CREATE TABLE event_editions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, year int NOT NULL, starts_at timestamptz, ends_at timestamptz, active boolean NOT NULL DEFAULT true);
CREATE TABLE volunteer_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), volunteer_user_id uuid NOT NULL REFERENCES users, event_edition_id uuid REFERENCES event_editions, department_id uuid NOT NULL REFERENCES departments, work_date date NOT NULL, started_at timestamptz, ended_at timestamptz, minutes_worked int NOT NULL CHECK(minutes_worked BETWEEN 1 AND 960), work_description text NOT NULL CHECK(length(work_description) BETWEEN 1 AND 2000), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','withdrawn')), submitted_at timestamptz, decided_at timestamptz, decided_by_user_id uuid REFERENCES users, decision_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version int NOT NULL DEFAULT 1, CHECK((started_at IS NULL AND ended_at IS NULL) OR (started_at IS NOT NULL AND ended_at>started_at)));
CREATE INDEX volunteer_queue ON volunteer_entries(department_id,status);
CREATE TABLE volunteer_approval_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES volunteer_entries, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, redeemed_at timestamptz, redeemed_by_user_id uuid REFERENCES users, revoked_at timestamptz);
CREATE TABLE volunteer_decision_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entry_id uuid NOT NULL REFERENCES volunteer_entries, actor_user_id uuid NOT NULL REFERENCES users, decision text NOT NULL CHECK(decision IN ('approved','rejected')), note text NOT NULL, method text NOT NULL CHECK(method IN ('qr','manual')), idempotency_key uuid UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE position_levels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text UNIQUE NOT NULL, personnel_level_id uuid REFERENCES personnel_levels, active boolean NOT NULL DEFAULT true, sort_order int NOT NULL DEFAULT 0);
CREATE TABLE organization_default_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text UNIQUE NOT NULL, label text NOT NULL, type text NOT NULL DEFAULT 'textarea', required boolean NOT NULL DEFAULT true, sensitive boolean NOT NULL DEFAULT false, max_length int NOT NULL DEFAULT 4000, sort_order int NOT NULL DEFAULT 0);
CREATE TABLE form_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, department_id uuid REFERENCES departments, created_by uuid REFERENCES users, active boolean NOT NULL DEFAULT true);
CREATE TABLE form_template_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES form_templates, version_number int NOT NULL, schema_json jsonb NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), UNIQUE(template_id,version_number));
CREATE TABLE position_postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, department_id uuid NOT NULL REFERENCES departments, position_level_id uuid NOT NULL REFERENCES position_levels, is_leadership boolean NOT NULL DEFAULT false, description_markdown text NOT NULL, status text NOT NULL CHECK(status IN ('draft','open','closed','archived')), created_by_user_id uuid NOT NULL REFERENCES users, hiring_owner_user_id uuid NOT NULL REFERENCES users, form_template_version_id uuid NOT NULL REFERENCES form_template_versions, opened_at timestamptz, closes_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_posting_id uuid NOT NULL REFERENCES position_postings, applicant_user_id uuid NOT NULL REFERENCES users, submitted_myfwa_id text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','screening','interviewing','offered','approved','rejected','withdrawn')), answers_json jsonb NOT NULL DEFAULT '{}', submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, decision_actor_id uuid REFERENCES users);
CREATE UNIQUE INDEX one_active_application ON applications(position_posting_id,applicant_user_id) WHERE status NOT IN ('rejected','withdrawn');
CREATE TABLE interviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES applications, scheduled_start_at timestamptz NOT NULL, scheduled_end_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'America/New_York', location_label text NOT NULL, location_url text, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('draft','scheduled','completed','cancelled')), created_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(scheduled_end_at>scheduled_start_at));
CREATE TABLE interview_participants (interview_id uuid REFERENCES interviews, interviewer_user_id uuid REFERENCES users, assigned_by_user_id uuid REFERENCES users, assigned_at timestamptz NOT NULL DEFAULT now(), response text NOT NULL DEFAULT 'pending' CHECK(response IN ('pending','approve','deny')), response_at timestamptz, recommendation_notes text, PRIMARY KEY(interview_id,interviewer_user_id));
CREATE TABLE interview_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interview_id uuid NOT NULL REFERENCES interviews, author_user_id uuid NOT NULL REFERENCES users, body text NOT NULL CHECK(length(body) BETWEEN 1 AND 10000), visibility text NOT NULL CHECK(visibility IN ('author_only','interview_panel','hr')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_final_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid UNIQUE NOT NULL REFERENCES applications, decision text NOT NULL CHECK(decision IN ('approve','deny')), decided_by_user_id uuid NOT NULL REFERENCES users, reason text NOT NULL, decided_at timestamptz NOT NULL DEFAULT now(), idempotency_key uuid UNIQUE NOT NULL);
CREATE TABLE saved_lists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', owner_user_id uuid NOT NULL REFERENCES users, shared_scope text NOT NULL DEFAULT 'private' CHECK(shared_scope IN ('private','hr','department')), filter_ast_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bulk_change_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_user_id uuid NOT NULL REFERENCES users, requested_filter_snapshot_json jsonb NOT NULL, target_user_ids_json jsonb NOT NULL, operation_json jsonb NOT NULL, preview_count int NOT NULL, status text NOT NULL DEFAULT 'previewed', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, result_json jsonb);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users, action text NOT NULL, resource_type text NOT NULL, resource_id uuid, scope_json jsonb NOT NULL DEFAULT '{}', before_json jsonb, after_json jsonb, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_time ON audit_events(created_at DESC);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_user_id uuid NOT NULL REFERENCES users, type text NOT NULL, payload_json jsonb NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable evidence cannot be changed'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_signatures BEFORE UPDATE OR DELETE ON term_signatures FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_decisions BEFORE UPDATE OR DELETE ON volunteer_decision_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_final_decisions BEFORE UPDATE OR DELETE ON application_final_decisions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_form_versions BEFORE UPDATE OR DELETE ON form_template_versions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE FUNCTION protect_published_term() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.published_at IS NOT NULL AND (TG_OP='DELETE' OR NEW.body_markdown IS DISTINCT FROM OLD.body_markdown OR NEW.body_sha256 IS DISTINCT FROM OLD.body_sha256 OR NEW.term_id IS DISTINCT FROM OLD.term_id OR NEW.version_number IS DISTINCT FROM OLD.version_number OR NEW.published_at IS DISTINCT FROM OLD.published_at OR NEW.published_by IS DISTINCT FROM OLD.published_by) THEN RAISE EXCEPTION 'Published terms are immutable'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER protect_terms BEFORE UPDATE OR DELETE ON term_versions FOR EACH ROW EXECUTE FUNCTION protect_published_term();

-- One policy function is used by list queries and record authorization. Rank never grants access.
CREATE FUNCTION has_permission(actor uuid, capability text, dept uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM permission_grants g WHERE g.user_id=actor AND g.permission=capability AND
 (g.scope_type='global' OR (g.scope_type='department' AND g.scope_id=dept) OR (g.scope_type='division' AND EXISTS(SELECT 1 FROM departments d WHERE d.id=dept AND d.division_id=g.scope_id))))
$$;
CREATE FUNCTION visible_person(actor uuid, subject uuid, capability text) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT has_permission(actor,capability,NULL) OR EXISTS(SELECT 1 FROM user_departments m WHERE m.user_id=subject AND m.ended_at IS NULL AND has_permission(actor,capability,m.department_id))
$$;
CREATE FUNCTION applicable_term(term uuid, person uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM terms t CROSS JOIN users u LEFT JOIN personnel_levels l ON l.id=u.personnel_level_id WHERE t.id=term AND u.id=person AND t.active AND t.effective_at<=now() AND (t.ends_at IS NULL OR t.ends_at>now()) AND
 (t.audience='all' OR (t.audience='volunteers' AND u.volunteer_eligible) OR (t.audience='personnel' AND l.rank IS NOT NULL)) AND
 (t.minimum_personnel_rank IS NULL OR l.rank>=t.minimum_personnel_rank) AND (t.requires_volunteer IS NULL OR t.requires_volunteer=u.volunteer_eligible))
$$;
CREATE VIEW people_directory AS SELECT u.id,u.myfwa_id,u.display_name,u.status,u.primary_department_id,u.personnel_level_id,u.volunteer_eligible,u.created_at,u.updated_at,l.label AS level,l.rank,d.name AS department,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('id',dd.id,'name',dd.name)) FROM user_departments m JOIN departments dd ON dd.id=m.department_id WHERE m.user_id=u.id AND m.ended_at IS NULL),'[]') AS departments,
 COALESCE((SELECT jsonb_agg(year ORDER BY year) FROM user_service_years y WHERE y.user_id=u.id AND verification_status='verified'),'[]') AS service_years,
 (SELECT count(*) FROM user_service_years y WHERE y.user_id=u.id AND verification_status='verified') AS verified_years,
 COALESCE((SELECT jsonb_agg(s.name) FROM user_skills us JOIN skills s ON s.id=us.skill_id WHERE us.user_id=u.id),'[]') AS skills
 FROM users u LEFT JOIN personnel_levels l ON l.id=u.personnel_level_id LEFT JOIN departments d ON d.id=u.primary_department_id;
